import cv2,numpy as np
from PIL import Image
im=np.array(Image.open('/app/target.png').convert('L'))
for th in [80,128,200,240]:
 m=(im<th).astype(np.uint8); n,l,st,c=cv2.connectedComponentsWithStats(m,8)
 print('th',th,'components',[(tuple(st[i]), tuple(np.round(c[i],1))) for i in range(1,n) if st[i,cv2.CC_STAT_AREA]>10])
print('threshold area',[(th,int((im<th).sum())) for th in [10,50,80,128,180,220,240]])
try:
 from skimage.morphology import skeletonize
 print('skimage available')
 sk=skeletonize(im<128); print('skelsum',sk.sum())
 ys,xs=np.where(sk); print('bbox',xs.min(),xs.max(),ys.min(),ys.max())
 # degree and endpoints/junctions
 k=np.ones((3,3),np.uint8); deg=cv2.filter2D(sk.astype(np.uint8),-1,k)-sk.astype(np.uint8)
 for d in [1,2,3,4,5,6,7,8]:
  yy,xx=np.where(sk&(deg==d));
  if len(xx): print('degree',d,len(xx),'sample',list(zip(xx[:15],yy[:15])))
except Exception as e:print('skerr',e)
