import numpy as np
from PIL import Image
im=np.array(Image.open('/app/target.png').convert('L'))
for th in [80,128,200,240]:
 m=im<th
 # connected components 8 neighbors iterative row-based flood fill
 H,W=m.shape; seen=np.zeros(m.shape,bool); comps=[]
 for y,x in zip(*np.where(m & ~seen)):
  if seen[y,x]: continue
  stack=[(y,x)];seen[y,x]=1; pix=[]
  while stack:
   yy,xx=stack.pop();pix.append((yy,xx))
   for dy in (-1,0,1):
    for dx in (-1,0,1):
     ny,nx=yy+dy,xx+dx
     if 0<=ny<H and 0<=nx<W and m[ny,nx] and not seen[ny,nx]:seen[ny,nx]=1;stack.append((ny,nx))
  if len(pix)>10:
   a=np.array(pix);comps.append((len(pix),a[:,1].min(),a[:,1].max(),a[:,0].min(),a[:,0].max()))
 print('th',th,'components',comps)
print('threshold area',[(th,int((im<th).sum())) for th in [10,50,80,128,180,220,240]])
